mapper.select:
SELECT *
FROM stock_watch_fact_observation
WHERE id > #{afterId}
ORDER BY id ASC
LIMIT #{limit}

SELECT *
FROM stock_watch_fact_observation
WHERE symbol = #{symbol}
  AND market = #{market}
  AND source_time_epoch_ms > #{afterSourceTimeEpochMs}
  AND source_time_quality IN ('FRESH', 'POST_CLOSE_VALID')
ORDER BY source_time_epoch_ms ASC, id ASC
LIMIT #{limit}
